/* ============================================================================
 * FacturaBot · Nodo 3 · "Procesar facturas"
 * ----------------------------------------------------------------------------
 * Jerarquía de clases (4 pilares de POO) + patrón Factory + Validador de negocio.
 * ========================================================================== */

/* ============================================================================
 * FacturaBot · Capa de dominio
 * ----------------------------------------------------------------------------
 * Práctica: "Programación Orientada a Objetos en el nodo Code de n8n"
 *
 * Este archivo es la FUENTE ÚNICA de verdad del dominio. El script
 * tools/build.mjs lo concatena dentro del nodo Code "Procesar facturas" y
 * tools/verificar.mjs lo ejecuta con Node para comprobar los resultados.
 *
 * Pilares de POO implementados aquí:
 *   1. ENCAPSULAMIENTO  -> campos privados (#) + getters de solo lectura
 *   2. HERENCIA         -> extends / super()
 *   3. POLIMORFISMO     -> sobrescritura de calcularImpuesto(), total(), toJSON()
 *   4. ABSTRACCIÓN      -> Factura es abstracta: calcularImpuesto() lanza Error
 *
 * Patrón adicional: FACTORY (FabricaFacturas) para crear la subclase correcta.
 * ========================================================================== */

/* ---------------------------------------------------------------------------
 * Error de negocio: transporta un código estable para poder clasificar el
 * rechazo sin depender de textos libres.
 * ------------------------------------------------------------------------ */
class ErrorFactura extends Error {
  constructor(mensaje, codigo = 'FACTURA_INVALIDA') {
    super(mensaje);
    this.name = 'ErrorFactura';
    this.codigo = codigo;
  }
}

/* ===========================================================================
 * 1) LineaFactura — ENCAPSULAMIENTO
 * ===========================================================================
 * No expone estado interno: la única forma de leer sus datos es a través de
 * getters, y la única forma de calcular su valor es el método subtotal().
 * ========================================================================= */
class LineaFactura {
  #descripcion;
  #cantidad;
  #precioUnitario;

  constructor({ descripcion, cantidad, precioUnitario }) {
    if (typeof descripcion !== 'string' || descripcion.trim() === '') {
      throw new ErrorFactura(
        'La descripción de la línea es obligatoria.',
        'LINEA_SIN_DESCRIPCION',
      );
    }
    if (!Number.isFinite(Number(cantidad)) || Number(cantidad) <= 0) {
      throw new ErrorFactura(
        `La cantidad de "${descripcion.trim()}" debe ser mayor que 0.`,
        'CANTIDAD_INVALIDA',
      );
    }
    if (!Number.isFinite(Number(precioUnitario)) || Number(precioUnitario) <= 0) {
      throw new ErrorFactura(
        `El precio unitario de "${descripcion.trim()}" debe ser mayor que 0.`,
        'PRECIO_INVALIDO',
      );
    }

    this.#descripcion = descripcion.trim();
    this.#cantidad = Number(cantidad);
    this.#precioUnitario = Number(precioUnitario);
  }

  get descripcion() {
    return this.#descripcion;
  }

  get cantidad() {
    return this.#cantidad;
  }

  get precioUnitario() {
    return this.#precioUnitario;
  }

  /** Valor de la línea: cantidad × precio unitario. */
  subtotal() {
    return this.#cantidad * this.#precioUnitario;
  }

  toJSON() {
    return {
      descripcion: this.#descripcion,
      cantidad: this.#cantidad,
      precioUnitario: this.#precioUnitario,
      subtotal: this.subtotal(),
    };
  }

  /**
   * Subtotal "tolerante" usado para facturas RECHAZADAS: ignora las líneas con
   * datos inválidos en lugar de lanzar. Permite mostrar cuánto dinero quedó
   * en disputa sin que el lote reviente.
   */
  static subtotalDe(lineas = []) {
    if (!Array.isArray(lineas)) return 0;
    return lineas.reduce((acumulado, linea) => {
      const cantidad = Number(linea?.cantidad);
      const precio = Number(linea?.precioUnitario);
      if (!Number.isFinite(cantidad) || !Number.isFinite(precio)) return acumulado;
      if (cantidad <= 0 || precio <= 0) return acumulado;
      return acumulado + cantidad * precio;
    }, 0);
  }
}

/* ===========================================================================
 * 2) Factura — CLASE BASE ABSTRACTA (abstracción + encapsulamiento)
 * ===========================================================================
 * - El detalle de líneas es privado (#lineas) y se expone con el getter
 *   `lineas`, que devuelve una copia congelada (inmutable para el exterior).
 * - calcularImpuesto() es un método abstracto: lanza Error si alguien intenta
 *   usar la base directamente.
 * - El constructor bloquea la instanciación directa de la clase abstracta.
 * ========================================================================= */
class Factura {
  #numero;
  #proveedor;
  #cedulaJuridica;
  #fecha;
  #lineas;

  constructor({ numero, proveedor, cedulaJuridica, fecha, lineas = [] }) {
    // Abstracción real: la base no se puede instanciar, hay que usar una subclase.
    if (new.target === Factura) {
      throw new TypeError(
        'Factura es una clase abstracta: use FabricaFacturas.crear() o una subclase.',
      );
    }

    this.#numero = numero ?? null;
    this.#proveedor = proveedor ?? null;
    this.#cedulaJuridica = cedulaJuridica ?? null;
    this.#fecha = fecha instanceof Date ? fecha : new Date(fecha);

    // Composición: el detalle crudo se convierte en objetos LineaFactura
    // (con datos inválidos, el constructor de LineaFactura lanza ErrorFactura).
    this.#lineas = Object.freeze(
      (Array.isArray(lineas) ? lineas : []).map((linea) =>
        linea instanceof LineaFactura ? linea : new LineaFactura(linea),
      ),
    );
  }

  get lineas() {
    return this.#lineas;
  }

  get numero() {
    return this.#numero;
  }

  get proveedor() {
    return this.#proveedor;
  }

  get cedulaJuridica() {
    return this.#cedulaJuridica;
  }

  get fecha() {
    return Number.isNaN(this.#fecha.getTime())
      ? null
      : this.#fecha.toISOString().slice(0, 10);
  }

  /** Tipo documental. Se sobrescribe en cada subclase (polimorfismo). */
  get tipo() {
    return 'base';
  }

  /** Tasa de impuesto vigente. Se sobrescribe en cada subclase. */
  get tasaImpuesto() {
    return 0;
  }

  /** Suma de las líneas, en la moneda original de la factura. */
  subtotal() {
    return this.#lineas.reduce((acumulado, linea) => acumulado + linea.subtotal(), 0);
  }

  /**
   * El subtotal expresado en colones (moneda nacional de Costa Rica).
   * En la base la moneda original ya es CRC; FacturaExtranjera lo sobrescribe
   * para aplicar el tipo de cambio.
   */
  subtotalColones() {
    return this.subtotal();
  }

  /** MÉTODO ABSTRACTO: cada subclase define su propia regla de IVA. */
  calcularImpuesto() {
    throw new Error(
      'calcularImpuesto() es un método abstracto: debe implementarse en la subclase.',
    );
  }

  /** Total en colones. Se sobrescribe en FacturaExtranjera (conversión). */
  total() {
    return this.subtotalColones() + this.calcularImpuesto();
  }

  toJSON() {
    return {
      numero: this.#numero,
      tipo: this.tipo,
      proveedor: this.#proveedor,
      cedulaJuridica: this.#cedulaJuridica,
      fecha: this.fecha,
      lineas: this.#lineas.map((linea) => linea.toJSON()),
      subtotal: this.subtotalColones(),
      impuesto: this.calcularImpuesto(),
      total: this.total(),
      moneda: 'CRC',
    };
  }
}

/* ===========================================================================
 * 3) FacturaNacional — HERENCIA + POLIMORFISMO (IVA 13 %)
 * ========================================================================= */
class FacturaNacional extends Factura {
  static TASA_IVA = 0.13;

  constructor(datos) {
    super(datos);
  }

  get tipo() {
    return 'nacional';
  }

  get tasaImpuesto() {
    return FacturaNacional.TASA_IVA;
  }

  /** POLIMORFISMO: aquí vive la regla del 13 %. */
  calcularImpuesto() {
    return Math.round(this.subtotal() * this.tasaImpuesto);
  }
}

/* ===========================================================================
 * 4) FacturaExenta — HERENCIA + POLIMORFISMO (IVA 0 % + motivo de exención)
 * ========================================================================= */
class FacturaExenta extends Factura {
  #motivoExencion;

  constructor(datos) {
    super(datos);
    this.#motivoExencion = String(datos?.motivoExencion ?? '').trim();
  }

  get motivoExencion() {
    return this.#motivoExencion;
  }

  get tipo() {
    return 'exenta';
  }

  get tasaImpuesto() {
    return 0;
  }

  /** POLIMORFISMO: exenta, sin IVA. */
  calcularImpuesto() {
    return 0;
  }
}

/* ===========================================================================
 * 5) FacturaExtranjera — HERENCIA + POLIMORFISMO (IVA 0 % y total en ₡)
 * ===========================================================================
 * El IVA es 0 (exportación de servicios) y el total se convierte a colones
 * usando el tipo de cambio de la factura.
 * ========================================================================= */
class FacturaExtranjera extends Factura {
  #moneda;
  #tipoCambio;

  constructor(datos) {
    super(datos);
    this.#moneda = String(datos?.moneda ?? '').toUpperCase();
    this.#tipoCambio = Number(datos?.tipoCambio);
  }

  get moneda() {
    return this.#moneda;
  }

  get tipoCambio() {
    return this.#tipoCambio;
  }

  get tipo() {
    return 'extranjera';
  }

  get tasaImpuesto() {
    return 0;
  }

  /** POLIMORFISMO: exenta de IVA por exportación de servicios. */
  calcularImpuesto() {
    return 0;
  }

  /** POLIMORFISMO: convierte el subtotal a colones con el tipo de cambio. */
  subtotalColones() {
    return Math.round(this.subtotal() * this.#tipoCambio);
  }

  /** POLIMORFISMO: sobrescribe total() para entregar el importe en colones. */
  total() {
    return this.subtotalColones() + this.calcularImpuesto();
  }

  toJSON() {
    return {
      ...super.toJSON(),
      monedaOriginal: this.#moneda,
      tipoCambio: this.#tipoCambio,
      subtotalOriginal: this.subtotal(),
    };
  }
}

/* ===========================================================================
 * 6) FabricaFacturas — PATRÓN FACTORY
 * ===========================================================================
 * Decide la subclase a instanciar a partir de `datos.tipo`.
 * Se usa un REGISTRO (mapa tipo → clase) en lugar de una cadena de if/else:
 *  - no hay `if` por tipo de factura (la prohibition de la guía),
 *  - es extensible: registrar un tipo nuevo es una línea, no un refactor.
 * ========================================================================= */
class FabricaFacturas {
  static #registro = {
    nacional: FacturaNacional,
    exenta: FacturaExenta,
    extranjera: FacturaExtranjera,
  };

  /** Tipos soportados por el workflow. */
  static tipos() {
    return Object.keys(FabricaFacturas.#registro);
  }

  /** ¿El workflow sabe procesar este tipo documental? */
  static soporta(tipo) {
    const clave = String(tipo ?? '').trim().toLowerCase();
    return Object.prototype.hasOwnProperty.call(FabricaFacturas.#registro, clave);
  }

  /** Registra un nuevo tipo (principio abierto/cerrado). */
  static registrar(tipo, clase) {
    FabricaFacturas.#registro[String(tipo).trim().toLowerCase()] = clase;
    return FabricaFacturas;
  }

  /**
   * Punto de entrada único: devuelve la instancia de la subclase correcta.
   * @throws {ErrorFactura} si el tipo no está soportado.
   */
  static crear(datos) {
    const clave = String(datos?.tipo ?? '').trim().toLowerCase();
    const Clase = FabricaFacturas.#registro[clave];

    if (!Clase) {
      throw new ErrorFactura(
        `El tipo "${datos?.tipo}" no está soportado. Tipos válidos: ${FabricaFacturas.tipos().join(', ')}.`,
        'TIPO_NO_SOPORTADO',
      );
    }

    return new Clase(datos);
  }
}

/* ===========================================================================
 * 7) ValidadorFactura — REGLAS DE NEGOCIO CON SEVERIDAD
 * ===========================================================================
 * Cada regla se clasifica como:
 *   ERROR      -> la factura se RECHAZA (se devuelve al proveedor).
 *   ADVERTENCIA -> la factura pasa a REVISIÓN (la ve gerencia).
 * Sin observaciones -> la factura queda APROBADA.
 * ========================================================================= */
class ValidadorFactura {
  /** Cédula jurídica costarricense: 3-XXX-XXXXXX (9 dígitos con guiones). */
  static CEDULA_COSTARRICENSE = /^3-\d{3}-\d{6}$/;

  static validar(datos = {}) {
    const errores = [];
    const advertencias = [];

    // 1) Número de factura: obligatorio.
    if (!datos.numero || String(datos.numero).trim() === '') {
      errores.push('El número de factura es obligatorio.');
    }

    // 2) Cédula jurídica costarricense: obligatoria y con formato válido.
    const cedula = String(datos.cedulaJuridica ?? '').trim();
    if (cedula === '') {
      errores.push('La cédula jurídica del proveedor es obligatoria.');
    } else if (!ValidadorFactura.CEDULA_COSTARRICENSE.test(cedula)) {
      errores.push(
        `La cédula jurídica "${cedula}" no cumple el formato 3-XXX-XXXXXX.`,
      );
    }

    // 3) Tipo documental: debe existir en el registro de la fábrica.
    if (!FabricaFacturas.soporta(datos.tipo)) {
      errores.push(
        `El tipo "${datos.tipo}" no está soportado. Tipos válidos: ${FabricaFacturas.tipos().join(', ')}.`,
      );
    }

    // 4) Fecha: obligatoria, válida y no futura.
    const fecha = new Date(datos.fecha);
    if (!datos.fecha || Number.isNaN(fecha.getTime())) {
      errores.push('La fecha de la factura es obligatoria y debe ser válida.');
    } else if (fecha.getTime() > Date.now()) {
      advertencias.push(
        `La fecha ${String(datos.fecha).slice(0, 10)} es futura: requiere validación de gerencia.`,
      );
    }

    // 5) Detalle: al menos una línea y cada línea con cantidad/precio > 0.
    const lineas = Array.isArray(datos.lineas) ? datos.lineas : [];
    if (lineas.length === 0) {
      errores.push('La factura debe tener al menos una línea de detalle.');
    }
    lineas.forEach((linea, indice) => {
      const numeroLinea = indice + 1;
      const descripcion = String(linea?.descripcion ?? '').trim();
      const cantidad = Number(linea?.cantidad);
      const precio = Number(linea?.precioUnitario);

      if (descripcion === '') {
        errores.push(`Línea ${numeroLinea}: la descripción es obligatoria.`);
      }
      if (!Number.isFinite(cantidad) || cantidad <= 0) {
        errores.push(`Línea ${numeroLinea}: la cantidad debe ser mayor que 0.`);
      }
      if (!Number.isFinite(precio) || precio <= 0) {
        errores.push(`Línea ${numeroLinea}: el precio unitario debe ser mayor que 0.`);
      }
    });

    return {
      valida: errores.length === 0,
      errores,
      advertencias,
    };
  }
}


/* ============================================================================
 * FacturaBot · Constantes compartidas por el workflow
 * ----------------------------------------------------------------------------
 * ESTADOS  -> valores exactos que evalúa el nodo Switch ({{ $json.estado }}).
 * ACCIONES -> texto que agrega cada nodo Set ("Aprobada" / "Revisión" /
 *             "Rechazada"). Deben coincidir con los nodos del workflow.
 * ========================================================================== */

const ESTADOS = {
  APROBADA: 'aprobada',
  REVISION: 'revision',
  RECHAZADA: 'rechazada',
};

const ACCIONES = {
  [ESTADOS.APROBADA]: 'Registrar en contabilidad',
  [ESTADOS.REVISION]: 'Enviar a gerencia',
  [ESTADOS.RECHAZADA]: 'Devolver al proveedor',
};

const MONEDA_LOCAL = 'CRC';


/* ============================================================================
 * FacturaBot · Capa de procesamiento (nodo 3 · "Procesar facturas")
 * ----------------------------------------------------------------------------
 * Traduce cada item de n8n a una factura (vía Factory), lo valida y devuelve
 * un registro normalizado con `estado`, que es el campo que consume el
 * nodo Switch ("Clasificar").
 * ========================================================================== */


/**
 * Procesa una factura cruda y devuelve el registro normalizado.
 * @param {object} datos factura tal como viene del nodo de datos de prueba
 */
function procesarFactura(datos = {}) {
  const validacion = ValidadorFactura.validar(datos);
  const errores = [...validacion.errores];
  const advertencias = [...validacion.advertencias];

  // La Factory decide la subclase; si el tipo no existe, lanza ErrorFactura.
  let instancia = null;
  try {
    instancia = FabricaFacturas.crear(datos);
  } catch (error) {
    // El tipo no soportado ya fue reportado por el validador: no se duplica.
    const yaReportado =
      error instanceof ErrorFactura && error.codigo === 'TIPO_NO_SOPORTADO';
    if (!yaReportado && validacion.errores.length === 0) {
      errores.push(error.message);
    }
  }

  const identidad = {
    numero: datos.numero ?? null,
    tipo: String(datos.tipo ?? '').trim().toLowerCase(),
    proveedor: datos.proveedor ?? null,
    cedulaJuridica: datos.cedulaJuridica ?? null,
    fecha: datos.fecha ?? null,
  };

  const lineas = Array.isArray(datos.lineas)
    ? datos.lineas.map((linea) => ({
        descripcion: String(linea?.descripcion ?? ''),
        cantidad: Number(linea?.cantidad),
        precioUnitario: Number(linea?.precioUnitario),
      }))
    : [];

  /* --- Factura rechazada: se reporta un monto REFERENCIAL (sin IVA) ------ *
   * y se marca para que el ReporteLote lo excluya de las sumas del lote.   */
  if (errores.length > 0) {
    const montoReferencial = LineaFactura.subtotalDe(datos.lineas);
    return {
      ...identidad,
      estado: ESTADOS.RECHAZADA,
      nivel: 'error',
      motivo: errores.join(' | '),
      errores,
      advertencias,
      lineas,
      subtotal: montoReferencial,
      impuesto: 0,
      total: montoReferencial,
      moneda: 'CRC',
      referencia: true,
    };
  }

  /* --- Factura válida: los montos salen de la instancia (polimorfismo) --- */
  const calculo = instancia.toJSON();

  return {
    ...identidad,
    ...calculo,
    estado: advertencias.length > 0 ? ESTADOS.REVISION : ESTADOS.APROBADA,
    nivel: advertencias.length > 0 ? 'aviso' : 'ok',
    motivo: advertencias.join(' | '),
    errores,
    advertencias,
    referencia: false,
  };
}

/**
 * Procesa el lote completo (el nodo Code corre "Run Once for All Items").
 * @param {Array<{json: object}>} items items de entrada de n8n
 */
function procesarLote(items = []) {
  return items.map((item) => procesarFactura(item?.json ?? item));
}


/* ==========================================================================
 * Ejecución del nodo (Run Once for All Items)
 * ======================================================================== */
const items = $input.all();
const registros = procesarLote(items);

return registros.map((json) => ({ json }));

/* ============================================================================
 * FacturaBot · Nodo 9 · "Reporte del lote"
 * ----------------------------------------------------------------------------
 * Instancia ReporteLote, consolida las métricas y devuelve un único ítem con el
 * ========================================================================== */

/* ============================================================================
 * FacturaBot · Constantes compartidas por el workflow
 * ----------------------------------------------------------------------------
 * ESTADOS  -> valores exactos que evalúa el nodo Switch ({{ $json.estado }}).
 * ACCIONES -> texto que agrega cada nodo Set ("Aprobada" / "Revisión" /
 *             "Rechazada"). Deben coincidir con los nodos del workflow.
 * ========================================================================== */

const ESTADOS = {
  APROBADA: 'aprobada',
  REVISION: 'revision',
  RECHAZADA: 'rechazada',
};

const ACCIONES = {
  [ESTADOS.APROBADA]: 'Registrar en contabilidad',
  [ESTADOS.REVISION]: 'Enviar a gerencia',
  [ESTADOS.RECHAZADA]: 'Devolver al proveedor',
};

const MONEDA_LOCAL = 'CRC';


/* ============================================================================
 * FacturaBot · Capa de presentación (paleta + render HTML)
 * ----------------------------------------------------------------------------
 * Genera el reporte visual del lote. El mismo renderizador se usa:
 *   - dentro del nodo Code "Reporte del lote" (nodo 9) para producir el HTML
 *     y el binario descargable, y
 *   - en tools/build.mjs para generar assets/reporte-lote.html.
 *
 * PALETA "Midnight Ledger": azul profundo + teal, sobre fondo casi negro,
 * con verde/ámbar/rojo reservados exclusivamente para los estados de negocio.
 * ========================================================================== */


const PALETA = Object.freeze({
  base: Object.freeze({
    fondo: '#070B14',
    superficie: '#0D1523',
    superficie2: '#131E33',
    borde: '#1E2B47',
    texto: '#E9EFFA',
    suave: '#8DA0C0',
  }),
  marca: Object.freeze({
    primario: '#3B82F6',
    primario2: '#60A5FA',
    teal: '#2DD4BF',
    violeta: '#A78BFA',
  }),
  estado: Object.freeze({
    [ESTADOS.APROBADA]: Object.freeze({ base: '#22C55E', texto: '#86EFAC', fondo: 'rgba(34,197,94,.12)' }),
    [ESTADOS.REVISION]: Object.freeze({ base: '#F59E0B', texto: '#FCD34D', fondo: 'rgba(245,158,11,.12)' }),
    [ESTADOS.RECHAZADA]: Object.freeze({ base: '#EF4444', texto: '#FCA5A5', fondo: 'rgba(239,68,68,.12)' }),
  }),
});

/** Formatea un monto en colones: 2622800 -> "₡2,622,800". */
function formatearMoneda(valor) {
  const numero = Number(valor) || 0;
  const negativo = numero < 0;
  const entero = Math.abs(Math.round(numero)).toString().replace(/\B(?=(\d{3})+(?!\d))/g, ',');
  return `${negativo ? '-' : ''}₡${entero}`;
}

/** Escapa texto para insertarlo con seguridad dentro del HTML. */
function escaparHTML(texto) {
  return String(texto ?? '')
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

/**
 * Codifica un texto a Base64 sin depender de Buffer ni btoa (no siempre
 * disponibles dentro del sandbox del nodo Code de n8n). Convierte a UTF-8
 * con encodeURIComponent y luego aplica el algoritmo Base64 estándar.
 */
function codificarBase64(texto) {
  const binario = encodeURIComponent(texto).replace(
    /%([0-9A-F]{2})/g,
    (_, hex) => String.fromCharCode(parseInt(hex, 16)),
  );
  const alfabeto = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/';
  let salida = '';

  for (let indice = 0; indice < binario.length; indice += 3) {
    const byte1 = binario.charCodeAt(indice);
    const byte2 = indice + 1 < binario.length ? binario.charCodeAt(indice + 1) : NaN;
    const byte3 = indice + 2 < binario.length ? binario.charCodeAt(indice + 2) : NaN;
    const bloque = (byte1 << 16) | ((Number.isNaN(byte2) ? 0 : byte2) << 8) | (Number.isNaN(byte3) ? 0 : byte3);

    salida += alfabeto[(bloque >> 18) & 63];
    salida += alfabeto[(bloque >> 12) & 63];
    salida += Number.isNaN(byte2) ? '=' : alfabeto[(bloque >> 6) & 63];
    salida += Number.isNaN(byte3) ? '=' : alfabeto[bloque & 63];
  }

  return salida;
}

const ETIQUETA_ESTADO = {
  [ESTADOS.APROBADA]: 'Aprobada',
  [ESTADOS.REVISION]: 'En revisión',
  [ESTADOS.RECHAZADA]: 'Rechazada',
};

const ORDEN_ESTADOS = [ESTADOS.APROBADA, ESTADOS.REVISION, ESTADOS.RECHAZADA];

/**
 * Renderiza el reporte completo en HTML autocontenido (sin dependencias
 * externas: ni CDN, ni fuentes remotas, ni scripts).
 * @param {object} resumen salida de ReporteLote.resumen()
 * @param {object} acciones mapa estado -> acción del workflow
 */
function renderReporteHTML(resumen, acciones = {}) {
  const facturas = resumen.facturas ?? [];
  const porEstado = resumen.porEstado ?? {};
  const total = resumen.totalFacturas ?? 0;
  const maximo = facturas.reduce((mayor, f) => Math.max(mayor, f.total ?? 0), 0) || 1;

  const segmentos = ORDEN_ESTADOS.map((estado) => {
    const porcentaje = total > 0 ? ((porEstado[estado] ?? 0) / total) * 100 : 0;
    const color = PALETA.estado[estado]?.base ?? '#3B82F6';
    return `<span class="seg" style="width:${porcentaje.toFixed(2)}%;background:${color}" title="${ETIQUETA_ESTADO[estado]}: ${porEstado[estado] ?? 0}"></span>`;
  }).join('');

  const leyenda = ORDEN_ESTADOS.map((estado) => {
    const color = PALETA.estado[estado]?.base ?? '#3B82F6';
    const texto = PALETA.estado[estado]?.texto ?? '#E9EFFA';
    return `<span class="chip"><i style="background:${color}"></i>${ETIQUETA_ESTADO[estado]}<b>${porEstado[estado] ?? 0}</b></span>`;
  }).join('');

  const filas = facturas
    .map((factura) => {
      const estado = factura.estado ?? ESTADOS.RECHAZADA;
      const color = PALETA.estado[estado]?.base ?? '#3B82F6';
      const ancho = Math.max(2, Math.round(((factura.total ?? 0) / maximo) * 100));
      const detalle =
        factura.tipo === 'extranjera' && factura.tipoCambio
          ? `<span class="nota">${escaparHTML(factura.monedaOriginal ?? '')} ${Number(factura.subtotalOriginal ?? 0).toLocaleString('en-US')} × ${factura.tipoCambio}</span>`
          : '';
      const motivo = factura.motivo
        ? `<div class="motivo">${escaparHTML(factura.motivo)}</div>`
        : '';
      const referencia = factura.referencia
        ? '<span class="marca-ref">monto referencial · no suma al lote</span>'
        : '';
      return `<tr style="--fila:${color}">
        <td class="num"><b>${escaparHTML(factura.numero ?? '—')}</b>${motivo}</td>
        <td><span class="tipo tipo--${escaparHTML(factura.tipo ?? '')}">${escaparHTML(factura.tipo ?? '—')}</span>${detalle}</td>
        <td>${escaparHTML(factura.proveedor ?? '—')}<div class="sub">${escaparHTML(factura.cedulaJuridica ?? '')}</div></td>
        <td class="fecha">${escaparHTML(factura.fecha ?? '—')}</td>
        <td><span class="pill pill--${estado}">${ETIQUETA_ESTADO[estado] ?? estado}</span></td>
        <td class="num">${formatearMoneda(factura.subtotal)}</td>
        <td class="num">${formatearMoneda(factura.impuesto)}</td>
        <td class="num total">${formatearMoneda(factura.total)}<div class="barra"><span style="width:${ancho}%;background:${color}"></span></div>${referencia}</td>
      </tr>`;
    })
    .join('\n');

  const tarjetasAccion = ORDEN_ESTADOS.map((estado) => {
    const color = PALETA.estado[estado]?.base ?? '#3B82F6';
    const fondo = PALETA.estado[estado]?.fondo ?? 'rgba(59,130,246,.12)';
    const texto = PALETA.estado[estado]?.texto ?? '#E9EFFA';
    return `<div class="accion" style="--color:${color};--fondo:${fondo};--texto:${texto}">
        <span class="accion__estado">${ETIQUETA_ESTADO[estado]}</span>
        <span class="accion__cuenta">${porEstado[estado] ?? 0} factura${(porEstado[estado] ?? 0) === 1 ? '' : 's'}</span>
        <span class="accion__texto">${escaparHTML(acciones[estado] ?? '—')}</span>
      </div>`;
  }).join('');

  const generadas = new Date(resumen.generadoEn ?? Date.now());
  const sello = Number.isNaN(generadas.getTime())
    ? new Date().toISOString().slice(0, 16).replace('T', ' ')
    : generadas.toISOString().slice(0, 16).replace('T', ' ');

  const proveedorFilas = (resumen.porProveedor ?? [])
    .map(
      (p) =>
        `<tr><td>${escaparHTML(p.proveedor)}</td><td class="num">${p.facturas}</td><td class="num">${formatearMoneda(p.total)}</td></tr>`,
    )
    .join('\n');

  const muestras = [
    ['Fondo', PALETA.base.fondo],
    ['Superficie', PALETA.base.superficie],
    ['Borde', PALETA.base.borde],
    ['Primario', PALETA.marca.primario],
    ['Teal', PALETA.marca.teal],
