    .map(
      ([nombre, hex]) =>
        `<div class="swatch"><span class="swatch__color" style="background:${hex}"></span><span class="swatch__name">${nombre}</span><span class="swatch__hex">${hex}</span></div>`,
    )
    .join('');

  return `<!DOCTYPE html>
